"Contact! Enemies ahead!":"Contact ! Ennemis devant !",
"Eyes on! Opening fire!":"Je les vois ! J'ouvre le feu !",
"Red visors, dead ahead!":"Visières rouges, droit devant !",
"Tank! Rockets ready!":"Char ! Roquettes prêtes !",
"Armor incoming, watch out!":"Blindés en approche, attention !",
"Air! Drones overhead!":"Air ! Drones au-dessus de nous !",
"Eyes up!":"Attention, en haut !",
"Reloading!":"Je recharge !",
"Cover me, swapping cells!":"Couvrez-moi, je change de batterie !",
"Empty! One sec!":"Vide ! Une seconde !",
"Covering!":"Je couvre !",
"Go, I got the flank!":"Vas-y, je tiens le flanc !",
