"Point is ours!":"Le point est à nous !",
"Beacon is flying our colours!":"La balise flotte à nos couleurs !",
"Commander's with us!":"Le commandant est avec nous !",
"Oh, you're back in line!":"Oh, te revoilà dans le rang !",
"You lead, we follow!":"Tu mènes, on te suit !",
"Commander, slow down!":"Commandant, doucement !",
"Wait up!":"Attends-nous !",
"Congrats on the promotion!":"Félicitations pour la promotion !",
"New stripes suit you!":"Les nouveaux galons te vont bien !",
"Pod inbound! Reinforcements!":"Capsule en approche ! Renforts !",
"Anyone remember why the sky is a portal?":"Quelqu'un se rappelle pourquoi le ciel est un portail ?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"On dit que si tu sautes dans le puits, tu ressors chez l'ennemi. Je ne teste pas.",
"The Swarm painted their visors red again. Show-offs.":"L'Essaim a encore peint ses visières en rouge. Frimeurs.",
"Ore, ore… when do we get some oil?":"Du minerai, du minerai… et le pétrole, on en aura quand ?",
"I dreamt I was a toaster. It was peaceful.":"J'ai rêvé que j'étais un grille-pain. C'était paisible.",
"Quiet. Too quiet.":"Silence. Trop de silence.",
"See that? Our base is above the Swarm base again. Portals, man.":"Vous avez vu ? Notre base est encore au-dessus de celle de l'Essaim. Les portails, hein.",
"Diman, if you're reading this — we need a vacation.":"Diman, si tu lis ça — il nous faut des vacances.",
