"New in v6.3":"Nouveautés de la v6.3",
"New in v6.2":"Nouveautés de la v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nouvel aspect du minerai : les filons sont des cristaux émeraude taillés et lumineux sur du basalte noir, avec étincelles et brume verte ; l'Extracteur est un piédestal hexagonal avec un dôme en nid d'abeille et une tour en treillis surmontée d'un feu-balise vert (bande et fanion aux couleurs de l'équipe)",
"New in v6.1":"Nouveautés de la v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Classe préférée comme dans Battlefield (U, chiffres après la mort) : le jeu te fait apparaître dans cette classe si elle est disponible",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Véhicules à la première personne (V — extérieur/cockpit) ; aide à la visée légère — dans les Paramètres",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Sortir du Noyau est facile : Espace — vers le puits, B — capsule vers la surface ; les effets des capacités se réinitialisent à la mort",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Progression sans fin : généraux et Maréchal ★, niveaux de carrière, maîtrise des armes et accessoires, médailles, contrats quotidiens — écran Carrière",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Stratégie : zoom fluide à la molette, icônes et étiquettes au-dessus des unités (Alt — toutes), panneau Troupes / Bâtiments à gauche",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"clic droit — attaque en chemin, double clic droit — marche en tirant en mouvement ; ordres rares dans « Plus d'ordres ▾ » ; pas de boutons en double",
"New in v6":"Nouveautés de la v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Armes de vrai shooter : balles instantanées, fusil à 720 coups/min, mitrailleuse, recul, visée au clic droit, chargeurs et rechargement R, marqueurs de touche",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Gravité plus lourde, jetpack réactif, dash sur Z ou double jetpack en l'air ; l'arme ne vole plus avec toi quand tu changes d'unité",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Ingénieurs : sélectionne un ingénieur, choisis un bâtiment, pose un plan ; Extractors sur les filons de minerai ; clique sur « MINERAI » pour voir les revenus et comment les accélérer",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Les boutons grisés restent cliquables : ils expliquent pourquoi et proposent une solution ; boutons plus grands, bandeau « En cours », « ▶ Contrôler », Tab — une seule touche de mode",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Caméra de stratégie sans saccades ni retournements, zoom vers le curseur, minicarte déplaçable à la souris",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nouveaux véhicules : pillard « Chacal », lance-roquettes « Grad » (roquettes à tête chercheuse), mortier « Martillo » ; le Swarm reçoit « Avispa », « Colmena », « Trebuchet »",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Le stratège garde ses ordres et cesse de spammer la voix ; les combats viennent à toi ; B — redéploiement, Shift+B — au cœur du combat ; boussole, H — quelle cible",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Action libre (K) et « j'agis seul » (J), F2 — préréglages ; Échap met en pause et reprend ; sauvegardes : emplacements, export et import de fichier",
"New in v5.3":"Nouveautés de la v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Vol : gravité plus forte loin de la météorite, C en l'air freine, la poussée dirige plus nettement ; plus de blocage dans le portail",
"New in v5":"Nouveautés de la v5",
"Endless war by default and battle scale: normal, large, epic":"Combat sans fin par défaut et échelle des combats : normale, grande, épique",
"Save and load the battle (autosave every 3 minutes)":"Sauvegarde et chargement du combat (et sauvegarde auto toutes les 3 minutes)",
"Squadmates with callsigns: portraits, health and live chatter":"Équipiers d'escouade avec indicatifs : portraits, santé et échanges radio en direct",
"Fog of war in strategy, friends and foes outlined differently":"Brouillard de guerre en stratégie, alliés et ennemis surlignés différemment",
"Camera fly-over when switching, portal aurora instead of rings":"Survol de la caméra au changement d'unité, aurore du portail à la place des anneaux",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Tâches annexes, raccourci par le ciel, modules de la première expédition avec provisions, cristaux, glace dans les cratères, tempêtes de poussière",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Entraînement, mode cinéma avec enregistrement vidéo, véhicules d'escorte fournis par le stratège",
