"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Terrain d'essai : bataille sans fin au centre de la carte avec renforts. X — posséder un soldat sur place",
"Polygon off — its units are back under AI command":"Terrain d'essai désactivé — ses unités sont repassées sous le commandement de l'IA",
