"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Téléphone : trois modes de sticks. Gauche seul — « auto » (fort aimant, balles plus faibles). Droite seul — la visée s'active toute seule, aimant plus fort, tir plus précis. Les deux — pas de visée, aimant et précision réduits. Le bouton 👁 à droite masque/rétablit le HUD.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Téléphone : stratégie simplifiée — ingénieur et bâtiments uniquement. Cartes à gauche (ingénieur, QG, caserne…) : appui — la caméra y va, la barre du bas montre quoi construire/produire. « Au combat » — en haut à gauche. L'armée se bat toute seule. Stratégie complète — Paramètres → Téléphone.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Possession — deux cases : « Escouades » et « Véhicules » (les véhicules sont désactivés par défaut sur téléphone — l'IA les conduit). Si les véhicules sont désactivés, E (téléphone : le bouton à droite) près d'un véhicule allié — prendre son canon : il roule tout seul, tu tires. L'ancien « ordre des classes personnalisé » est dans « Avancé ». Une unité répond par radio quand tu la possèdes.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Indices intelligents : les indices de base s'éteignent après le 2e lancement, mais le jeu te signale une fonction que tu n'utilises jamais. Cases : de base / avancés / rares, et une séparée pour la voix des indices et du Curateur.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Le réflexe se charge avec les éliminations (les séries chargent plus). Tes équipiers sont à la traîne ou morts — le stratège t'en largue de nouveaux (plus cher qu'un renfort normal). Les graphismes et le son v7.2gfx sont intégrés : explosions en volutes, fumée, débris, acoustique des puits et des cratères. La date de build est enfin réelle.",
