"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"La carrière et les sauvegardes restent intactes. En combat, le même menu est le bouton « 🛠 Menu » en haut à droite{0}.",
"New developer match":"Nouvelle partie développeur",
"all unlocked, endless ore, instant build, arsenal":"tout débloqué, minerai infini, construction instantanée, arsenal",
"Trainings — all 4":"Entraînements — les 4",
