"Cinema: everything built":"Cinéma : tout construit",
"both bases built and upgraded — for footage":"les deux bases construites et améliorées — pour filmer",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mode cinéma — écran partagé : à gauche le bot stratège (vue du dessus de la base et de l'armée), à droite le bot tireur à la première personne. Boutons en bas (touches S, P) : « Écran partagé » et « ★ Tout construit » — les deux bases construites et améliorées pour filmer.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Le noyau et les tunnels traversant la météorite n'existent plus — la météorite est pleine, le combat se déroule uniquement en surface.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Téléphone : 👁 masque le HUD mais garde le jetpack, ⇆, les sticks et le marqueur d'objectif. « ◎ Visée » (doigt droit uniquement) — un aimant nettement plus fort et plus large ; la force de l'aimant pour les trois modes — Paramètres → Commandes → « Avancés ». Sur le canon d'un véhicule, le bouton affiche « Descendre ».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Entraînement : sur téléphone, uniquement les entraînements téléphone ; sur PC, uniquement ceux du PC. Les 4 sont dans le menu « 🛠 Développeur ». Le mode développeur et l'Arsenal forment désormais un seul menu (en combat — « 🛠 Menu » en haut à droite, F8 sur PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Styles graphiques « Dendy (8 bits) » et « 16 bits » : Paramètres → Graphismes → « Style graphique » (détails — bouton ⚙). Si les FPS passent sous 24 pendant les ~10 premières secondes d'une partie, Dendy s'active tout seul (sous 20 — pixels encore plus gros, 120 lignes) ; l'avis « revenir à la normale » rétablit définitivement les graphismes normaux. Ton choix dans le menu prime toujours.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Modèles 3D d'environnement (ruines, épaves, fortifications) — uniquement ceux bien notés, chargés à la demande. Pour désactiver : Paramètres → Graphismes → « Nouveaux modèles 3D d'environnement ».",
