"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Construction par les soldats : E (téléphone : « Entrer ») près de ton chantier — le soldat construit lui-même, les coéquipiers proches aident. Si les ingénieurs sont occupés, le stratège te demande de l'aide — marqueur « CHANTIER ».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Marques du stratège : le stratège place ⌖ sur un groupe d'ennemis près de toi — l'artillerie frappe 8 s plus tard et les lance-roquettes multiples « Grad » alliés proches tirent une salve. Ta propre frappe d'artillerie depuis la stratégie bénéficie aussi du soutien des « Grad ».",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Caches d'armes dans les conteneurs de fret et les satellites écrasés (📦 visible à 70 m) : E — une mitrailleuse lourde pendant 90 s, munitions incendiaires ou roquettes, plus le plein de grenades. Ramper : Ctrl — se coucher / se relever (visée plus basse et plus stable, mais lente).",
