"Camera shake":"Secousses de la caméra",
"Slow-mo on major kills":"Ralenti sur les éliminations importantes",
"\"What to do now\" hint":"Indice « quoi faire maintenant »",
"from blasts and hits, gentle":"dues aux explosions et aux coups, légères",
