"Link copied":"Lien copié",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"« ▶ Jouer » — le premier bouton du menu : un court survol sous le ciel-portail et direct au combat (passer — n'importe quelle touche ou un appui).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Les impacts se ressentent : son métallique et étincelles, marqueur d'élimination au viseur (tir à la tête — jaune), série ×N, secousses douces des explosions, ralenti sur les éliminations clés. Secousses, ralenti et indice se désactivent dans les Paramètres.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Bilan de la partie : durée, éliminations, meilleure série, ★ MVP et meilleure escouade, carte de partie — « ⇪ Partager », PNG ou lien du jeu.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Un indice « quoi faire maintenant » à gauche sous les ressources : ordre du stratège, point à capturer, attaque de l'Essaim. ✕ ou F7 — réduire.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Le combat se sauvegarde tout seul si tu fermes ou réduis l'onglet — « ⟲ Continuer » dans le menu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"La v7.5 reste dans le menu « 🕘 Version du jeu » au cas où la nouvelle ne te plairait pas. Les statistiques anonymes (sans noms ni e-mails) sont désormais envoyées ; à désactiver dans les Paramètres.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"« Jouer », retour des impacts, bilan de partie avec carte, indice « quoi faire », sauvegarde auto",
"and older: v7.5, v7.4, milestones v1–v7.0":"et plus anciennes : v7.5, v7.4, étapes v1–v7.0",
"New in v7.6":"Nouveautés de la v7.6",
"NEW IN v7.6":"NOUVEAUTÉS DE LA v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Choix de la faction avant la partie : le « Consortium » (infanterie lourde en armure assistée, blindage et artillerie) ou l'« Essaim » (vitesse, meutes de drones, tirs lourds avec distorsion). L'IA joue l'autre. Le choix est mémorisé.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Chaque faction a ses propres véhicules et son unique : le Consortium — le char « Rhino » et les « Plaques en céramite », l'Essaim — la « Meute de drones » et les « Jetpacks de phase ». Équilibrage vérifié par des parties de bots.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Cratères d'explosion : l'artillerie, les roquettes et les canons de char creusent des fosses dans la météorite — on peut les traverser à pied ou en véhicule et s'y mettre à couvert.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Vue à la troisième personne pour les soldats (V, mémorisée ; sur téléphone — Contrôles) et caméra fluide pour les véhicules avec un repère là où le canon va toucher.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"La v7.6 reste dans le menu « 🕘 Version du jeu » au cas où tu la préférerais.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Factions Consortium / Essaim avec choix avant la partie, cratères d'explosion, vue à la troisième personne",
"and older: v7.6, v7.5, milestones v1–v7.0":"et anciennes : v7.6, v7.5, jalons v1–v7.0",
