"Anomaly ahead":"Anomalie devant",
"dormant":"inactive",
"Anomaly ahead! The vein is singing — go around!":"Anomalie devant ! La veine chante — on contourne !",
"Hear that hum? A singing vein. Keep clear!":"Tu entends ce grondement ? Une Veine Chantante. N'approche pas !",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalie ! L'air tourbillonne — c'est un Tourbillon, contourne-le !",
"Rocks floating in the air… A whirlpool! Stay out!":"Des rochers en suspension dans l'air… Un Tourbillon ! Reste à l'écart !",
"Anomaly ahead — it is crackling with current!":"Anomalie devant — ça crépite de courant !",
"Rods and lightning — a Crackler. It loves armour!":"Des tiges et des éclairs — un Crépiteur. Il adore les blindages !",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalie ! Le sol tremble de chaleur — un Brasero !",
"Careful, a Brazier underfoot!":"Attention, un Brasero sous tes pieds !",
"Anomaly — green mist! Acid, hold your breath!":"Anomalie — brume verte ! De l'acide, on retient son souffle !",
"The mist is drifting our way, go around!":"La brume avance vers nous, on contourne !",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalie ! L'air est comme du verre — une Lentille, elle dévie les balles !",
"Everything is warping… a Lens nearby!":"Tout se déforme… une Lentille à proximité !",
"Ha! An enemy walked right into the anomaly!":"Ha ! Un ennemi est entré droit dans l'anomalie !",
"Got him! Lure them into anomalies!":"Touché ! Attire-les dans les anomalies !",
"Beautiful zap! One less tin can.":"Belle décharge ! Une boîte de conserve en moins.",
"The anomaly got me!":"L'anomalie m'a touché !",
"Ow! Don't go in there!":"Aïe ! N'y va pas !",
"Discharged! It is dormant now.":"Déchargée ! Elle est inactive maintenant.",
"Clear, the anomaly is discharged.":"Zone dégagée, l'anomalie est déchargée.",
"They say veins hide artifacts. Only first the vein sings…":"Il paraît que les veines cachent des artefacts. Mais d'abord, la veine chante…",
"Throw a bolt first, then walk. Old habit.":"Lance d'abord un boulon, ensuite avance. Vieille habitude.",
