"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor : plus de 100 morceaux d'EDMITRY directement dans le jeu — bouton 📻 (PC : touche 5, [ ] — morceau). La musique est diffusée à la demande et n'alourdit pas le jeu ; volume et lancement auto dans les Paramètres, plus un lien « Écouter sur Spotify ».",
