"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 à droite — Radio Portal Meteor : la musique d'EDMITRY pendant le combat.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor : la musique d'EDMITRY pendant le combat. [ ] — morceau.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY) : volume",
"Radio: start by itself in battle":"Radio : se lancer toute seule en combat",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja : une cyborg armée d'une katane. Débloquée à la Caserne grâce à la recherche « Protocole Ombre » (nécessite une Usine de mechs). Elle se téléporte seule dans les zones ennemies, taille les ennemis en pièces (pas de sang — des étincelles), enchaîne bonds, shurikens et duels contre le ninja ennemi. Possède-la — mode AUTO ou contrôle manuel (boutons dédiés sur téléphone).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor : 103 morceaux d'EDMITRY directement dans le jeu. Touche 5 (réassignable), sur téléphone — ☰ → Paramètres → Son. Volume et « lancer auto en combat » dans les paramètres ; la musique baisse pendant les explosions et la voix radio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Nouvelles langues : ouzbek et tadjik — complètes ; chinois, espagnol, portugais — partielles. Nouveau sélecteur de langue dans le menu à côté de « Nouvelle partie ».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Téléphone : « masquer les icônes » 👁 regroupe les boutons restants en une colonne bien rangée au bord droit ; le mode portrait ne se chevauche plus ; iPhone — le jeu n'entre plus en conflit avec les gestes de Safari, et « Partager → Sur l'écran d'accueil » le lance en plein écran.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Issu de la v7.8.1 : menu ☰ dans le coin (pause, recommencer, entraînement, graphismes), plus de Dendy automatique, bouton d'action ✋ sur téléphone. Les v7.8.1 et v7.8 restent dans le menu « 🕘 Version du jeu ».",
