"The new squad is selected — RMB on the red \"ATTACK\" marker.":"La nouvelle escouade est sélectionnée — clic droit sur le marqueur rouge « ATTAQUE ».",
"The new squad is selected — tap the red \"ATTACK\" marker.":"La nouvelle escouade est sélectionnée — appuie sur le marqueur rouge « ATTAQUE ».",
"💥 Methane exploded! The fog over the lake burned away":"💥 Le méthane a explosé ! Le brouillard au-dessus du lac s'est consumé",
"Ice — slippery, hard to stop":"Glace — ça glisse, difficile de s'arrêter",
