"✈ AIR RAID! Swarm carpet bombing — get off the red strip!":"✈ RAID AÉRIEN ! Bombardement en tapis de l'Essaim — quitte la bande rouge !",
"♨ AIR RAID! Swarm napalm — get out of the red circle!":"♨ RAID AÉRIEN ! Napalm de l'Essaim — sors du cercle rouge !",
"Air raid! Bomber overhead!":"Raid aérien ! Bombardier au-dessus de nous !",
"Carpet bombing":"Bombardement en tapis",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Un bombardier largue 10 bombes sur une bande de 80 m, en venant de ta base (en combat — dans l'axe de ton regard). Après 3,5 s, laisse des cratères.",
"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Une zone de feu de 12 m brûle pendant 9 secondes : dégâts continus, suppression, fumée. Après 2,5 s. Enflamme le méthane.",
"Bomber: target received, inbound!":"Bombardier : cible reçue, on arrive !",
"Attack jet: napalm inbound!":"Chasseur d'assaut : napalm en approche !",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Soutien : caisse, reconnaissance, « Grad », frappe d'artillerie, bombardement en tapis, napalm (puis 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ Pluie de météorites dans 10 s — mets-toi à couvert : hangar dans les rochers, sous une crête !",
"Warning: meteor shower! Everyone take cover":"Attention : pluie de météorites ! Tout le monde à couvert",
"Meteor shower in ":"Pluie de météorites dans ",
" s — take cover":" s — à couvert",
"Concrete barrier":"Barrière en béton",
"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Consortium. Section de mur de 7 m : arrête balles, obus et véhicules. Pose-les à la chaîne (Shift+clic).",
"Repair post":"Poste de réparation",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Consortium. Répare véhicules, bâtiments et infanterie dans un rayon de 26 m.",
"Tunnel burrow":"Terrier-tunnel",
"Swarm. Tunnel entrance: then \"Dig the exit\" to a point up to 220 m away — infantry travels underground.":"Essaim. Entrée de tunnel : puis « Creuser la sortie » vers un point jusqu'à 220 m — l'infanterie passe sous terre.",
"Tunnel exit":"Sortie du tunnel",
"Swarm. Tunnel exit. Destroy it and the tunnel collapses.":"Essaim. Sortie du tunnel. Détruis-la et le tunnel s'effondre.",
"Appears by itself when the tunnel breaks through":"Apparaît de lui-même quand le tunnel est percé",
