"Tunnel open! Select squads → \"Into tunnel\" on the card":"Tunnel percé ! Sélectionne des escouades → « Dans le tunnel » sur la carte",
"Tunnel open! Select squads → \"Into tunnel\" on the card or RMB the burrow":"Tunnel percé ! Sélectionne des escouades → « Dans le tunnel » sur la carte ou clic droit sur le terrier",
"The tunnel is through. Ready to move":"Le tunnel est percé. On peut passer",
"⚠ The Swarm broke through from underground! Destroy the \"Tunnel exit\"":"⚠ L'Essaim a surgi du sous-sol ! Détruis la « Sortie du tunnel »",
"The tunnel collapsed":"Le tunnel s'est effondré",
"The Swarm tunnel collapsed":"Le tunnel de l'Essaim s'est effondré",
"{0} is out of the tunnel":"{0} est sorti du tunnel",
"Tunnel: you are at the other end":"Tunnel : tu es à l'autre bout",
"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ Grondement souterrain : l'Essaim creuse un tunnel ! Percée dans ~10 s — prépare-toi",
"Warning! Digging heard. The enemy is tunnelling":"Attention ! On entend creuser. L'ennemi creuse un tunnel",
"Needs a Tunnel burrow — builders make it":"Il faut un Terrier-tunnel — les ingénieurs le construisent",
"The burrow is still being built":"Le terrier est encore en construction",
