"Tap the exit point (up to {0} m from the burrow)":"Appuie sur le point de sortie (jusqu'à {0} m du terrier)",
"LMB — exit point (up to {0} m from the burrow), RMB — cancel":"Clic gauche — point de sortie (jusqu'à {0} m du terrier), clic droit — annuler",
"Dig the exit first":"Creuse d'abord la sortie",
"Into the tunnel: {0} squad(s)":"Dans le tunnel : {0} escouade(s)",
"no squads within 70 m of the burrow — select squads and RMB/tap the burrow":"aucune escouade dans les 70 m du terrier — sélectionne des escouades puis clic droit/appui sur le terrier",
"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"Creusement : {0} s. L'ennemi entendra le grondement 10 s avant la percée",
"Exit · {0} m · {1} s":"Sortie · {0} m · {1} s",
"Dig the exit":"Creuser la sortie",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Essaim. Choisis un point jusqu'à 220 m — la sortie perce en 24 s. 10 s avant, l'ennemi entend un grondement et voit de la poussière.",
"Squads into the tunnel":"Escouades — dans le tunnel",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"Essaim. Les escouades dans les 70 m du terrier (et celles sélectionnées) passent par le tunnel et ressortent à l'autre bout. Ou : sélectionne des escouades et clic droit/appui sur le terrier.",
