"Walker":"Marcheur",
"Assembly hall":"Atelier d'assemblage",
"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Consortium. À partir de 12:00. On y assemble le char super-lourd « Bastion » (un par armée).",
"Incubator":"Incubateur",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Essaim. À partir de 12:00. On y fait pousser le marcheur « Reaper » (un par armée).",
"Super-heavy tank \"Bastion\"":"Char super-lourd « Bastion »",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Consortium. Boss : 15000 de coque, canon, 2 mitrailleuses, roquettes. Très lent. Point faible — l'arrière. Un par armée.",
"Walker \"Reaper\"":"Marcheur « Reaper »",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Essaim. Boss : 12500 de coque, rayon de distorsion, piétinement. Enjambe les barrières. Point faible — le noyau sous le ventre. Un par armée.",
