"assembling":"assemblage",
"boss deployed":"boss déployé",
"ready to assemble":"prêt à assembler",
"ours":"allié",
"key":"touche",
"Strip: ⟳ to rotate, or drag from the target along the run":"Bande : ⟳ pour pivoter, ou glisse depuis la cible dans le sens de l'approche",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Bande : molette de la souris ou R pour pivoter, ou glisse depuis la cible dans le sens de l'approche",
"Into the tunnel: {0} vehicle(s)":"Dans le tunnel : {0} véhicule(s)",
"Light and medium vehicles go into the nearest open tunnel":"Les véhicules légers et moyens entrent dans le tunnel ouvert le plus proche",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Essaim. Les escouades à moins de 70 m du terrier (et celles sélectionnées), ainsi que les véhicules légers/moyens sélectionnés (« Chacal », « Hammer », « Grad »), passent par le tunnel et ressortent à l'autre bout. Ou : sélectionne puis clic droit/appui sur le terrier.",
"Air strikes":"Frappes aériennes",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Bombardement en tapis et napalm : visée, rotation de la bande, alerte ennemie, appel en plein combat",
"Terrain and lakes":"Relief et lacs",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"La lave brûle, la glace fait glisser, le méthane explose au contact du feu, le hangar dans la roche sert d'abri",
"Swarm: tunnels":"Essaim : tunnels",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Tu joues l'Essaim : Terrier-tunnel, sortie jusqu'à 220 m, alerte par la poussière, escouades et véhicules dans le tunnel",
"Consortium: fortifications":"Consortium : fortifications",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Tu joues le Consortium : barrières en béton en chaîne, poste de réparation, réparation de terrain par les ingénieurs",
"Bosses":"Boss",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"« Bastion » et « Reaper » : à partir de 12:00 (temps avancé dans la leçon), atelier, assemblage, ordres, points faibles, possession",
