"The bomber took off from the base — into the sky, it will come out over the target":"Le bombardier a décollé de la base — il file dans le ciel et surgira au-dessus de la cible",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Sélectionne une unité → « ▶ Posséder » ou double appui. Bouton de mode en haut à droite : Stratège → Commandant → Tireur.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Sélectionne une unité → « ▶ Posséder » ou double clic. {0} — en boucle : Stratège → Commandant → Tireur.",
