"Living world":"Monde vivant",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Tes unités demandent de l'aide et te récompensent, les héros donnent des quêtes, un front enlisé se brise par une opération",
"A request":"Une demande",
"Breakthrough":"Point de bascule",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Tes unités te demandent parfois de l'aide : un appel radio, une carte DEMANDE et un marqueur ✋. Une escouade est clouée au sol — détruis les ennemis près d'elle. Récompense : un soldat par capsule depuis la base, une arme du coffre d'un buggy, la place de mitrailleur ou une couverture orbitale. Pas envie — ✕ ou ignore simplement.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Le vétéran éclaireur « Hibou » propose une quête. Y — accepter (N — refuser). Va au marqueur ★, élimine les gardes et reste 3 s près du pilote — il rejoint ton escouade.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Le front est bloqué — le QG propose une percée. Y — accepter. Tiens le relais 8 s sans ennemis à proximité : la carte ennemie est révélée 60 s. Le générateur — les tourelles ennemies se taisent 2 min. En Stratège — « Assigner une escouade ». L'ennemi peut aussi le faire : surveille le ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Tes unités demandent de l'aide : une carte DEMANDE et un marqueur ✋. Détruis les ennemis près de l'escouade clouée au sol — tu auras une récompense. ✕ — ignorer.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Le héros « Hibou » propose une quête — appuie sur « Accepter ». Va en ★, élimine les gardes, reste près du pilote.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Le front est bloqué — appuie sur « Accepter » et tiens le relais 8 s : la carte ennemie se révèle pour une minute.",
"Pod redeploy from the base: {0} m — through the sky portal":"Transfert par capsule depuis la base : {0} m — via le portail céleste",
"Pod away from the base! Hold on — exit over the target.":"Capsule partie de la base ! Accrochez-vous — sortie au-dessus de la cible.",
"Landed at the objective!":"Largage à l'objectif !",
