"Repairs others":"Répare les alliés",
"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Construit bâtiments et extracteurs, répare, retire le Duvet d'acier des alliés.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Une escouade arrive de la rampe de lancement de la base par le portail céleste, droit sur la cible.",
