"Engineer":"Ingénieur",
"Members: ":"Composition : ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Char de combat principal : canon et mitrailleuse. Le « Bouledogue » du Consortium est plus robuste, l'« Araignée » de l'Essaim plus rapide.",
"Heavy tank":"Char lourd",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Tireur volant autonome : rapide, fragile, craint l'antiaérien.",
"Upgrade":"Amélioration",
"Longer, faster jetpacks for all infantry.":"Jetpacks plus longs et plus rapides pour toute l'infanterie.",
"Extractors mine more ore.":"Les extracteurs produisent plus de minerai.",
"Army-wide levels: less damage taken / more damage dealt.":"Niveaux pour toute l'armée : moins de dégâts subis / plus de dégâts infligés.",
"Levels":"Niveaux",
"Base":"Base",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Cœur de la base : escouades, ingénieurs, capsules, recherches. Le perdre, c'est perdre la partie.",
"Produces: ":"Produit : ",
"Launch pad":"Rampe de lancement",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Un silo près du QG : capsules, caisses de ravitaillement et bombardiers partent d'ici à travers le portail céleste. On ne peut rien construire dessus.",
"Economy":"Économie",
"Key building":"Bâtiment clé",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Point faible — l'arrière (moteur) : dégâts ×{0}. Canon, 2 tourelles de mitrailleuse, nacelle de roquettes ; tourne très lentement — contournez-le par le flanc.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Point faible — le noyau lumineux sous le ventre : dégâts par en dessous ×{0}. Rayon de distorsion et piétinement de zone ; enjambe les barrières — gardez vos distances, ne restez pas groupés.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Contre : bombes et artillerie (×{0}), roquettes (×{1}), bombardement en tapis ; les balles l'égratignent à peine (×{2}).",
"Faction":"Faction",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Machines rapides, meutes de drones, tunnels et régénération. Infanterie plus légère mais plus rapide ; canons et rails frappent plus fort.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Infanterie lourde en armure assistée, barrières en béton, réparation et artillerie. Plus lent mais plus robuste.",
"Infantry HP":"PV de l'infanterie",
"Infantry speed":"Vitesse de l'infanterie",
