"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Joue et pense à voix haute : ce qui n'est pas clair, ce qui agace, ce qui plaît. Le coin de l'écran affiche la version, l'heure et les FPS — ils permettent de faire correspondre l'enregistrement aux notes.",
