"You run and shoot yourself. That is how you have played so far.":"Tu cours et tires toi-même. C'est comme ça que tu as joué jusqu'ici.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Tu regardes d'en haut et commandes toute l'armée : tu construis la base, tu envoies des escouades. L'armée se bat aussi toute seule.",
"You lead one squad: the camera is above it, tap the ground to move.":"Tu diriges une escouade : la caméra est au-dessus, appuie sur le sol pour y aller.",
