"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Aide masquée — « ? » la rouvre. Pour quitter la leçon : ☰ → « Quitter la leçon »",
"◎ precise":"◎ précis",
